int findFurthestReach(int currentPosition, int remainingHeight) {
    if (currentPosition >= stringLength) return stringLength;
    if (furthestReach[currentPosition][remainingHeight] >= 0) return furthestReach[currentPosition][remainingHeight];
    int bestPosition = currentPosition;
    for (int digit = 1; digit <= 9; digit++) {
        if (digitValue[currentPosition] != digit) continue;
        if (remainingHeight - digit < 0) continue;
        bestPosition = max(bestPosition, findFurthestReach(lastOccurrence[digit][currentPosition] + 1, remainingHeight - digit));
    }
    return furthestReach[currentPosition][remainingHeight] = bestPosition;
}

