        for (int digit = 1; digit <= 9; digit++) {
            if (digitValue[i] == digit) lastOccurrence[digit][i] = i;
            else lastOccurrence[digit][i] = i < stringLength - 1 ? lastOccurrence[digit][i + 1] : stringLength;
