        dp1[i][1] = dp1[i - 1][0] * all[__builtin_popcount(i) - 1] + dp1[i - 1][1];
    }

    dp2[(1 << all.size()) - 1][0] = 0;
    dp2[(1 << all.size()) - 1][1] = 1;
    for (int i = (1 << all.size()) - 2; i >= 0; i--) {
        dp2[i][0] = dp2[i + 1][0] + dp2[i + 1][1] * all[__builtin_popcount(i)];
        dp2[i][1] = dp2[i + 1][1] * (1 - all[__builtin_popcount(i)]);
