void deal() {
    last = 0;
    sett[0] = 1;
    while (last >= 0) {
        int id = sett[last];
        last--;
        int cnt = 0, les = G[id].size();
        for (int i = 0; i < les; i++) cnt += Size[G[id][i]];
        for (int i = 0; i < les; i++) {
            int u = rand() % cnt;
            for (int j = 0; j < les; j++) {
                u -= Size[G[id][j]];
                if (u < 0) {
                    q[++len] = sch[G[id][j]];
                    sett[++last] = G[id][j];
