int dp[600][600];
const int M = 100003;

bool canPlace(int pos, int i, int mark) {
    return mark - pos >= pos - i;
}

int calculatePermutations(int D) {
    int result = 1;
    for (int i = 1; i <= D; i++) {
        result *= i;
        result %= M;
    }
    return result;
}

int calculate(int pos, int i, int mark) {
    if (pos == mark || i == 0)
        return 1;
    if (i > pos || mark < pos)
        return 0;
    return calculatePermutations(mark - i);
}

int solveRecursively(int mark, int pos) {
    if (pos == 0)
        return 1;
    if (dp[mark][pos] != -1)
        return dp[mark][pos];
    int result = 0;
    for (int i = 0; i < pos; i++) {
        if (canPlace(pos, i, mark)) {
            result += ((long long)calculate(pos, i, mark) * solveRecursively(pos, i)) % M;
            result %= M;
        }
    }
    return dp[mark][pos] = result;
}

int main() {
    int T;
    cin >> T;
    for (int t = 1; t <= T; t++) {
        int n;
        cin >> n;
        memset(dp, -1, sizeof(dp));
        int result = 0;
        for (int i = 1; i < n; i++) {
            result += solveRecursively(n, i);
            result %= M;
        }
        cout << "Case #" << t << ": " << result << endl;
    }
    return 0;
}

