        if (x <= mx && y <= my) {
            if (!n->L) n->L = new tnode(n->sx, n->sy, mx, my);
            insertPoint(n->L, y, x);
        } else {
            if (!n->R) n->R = new tnode(mx + 1, n->sy, n->lx, my);
            insertPoint(n->R, y, x);
        }
    }
}

int countPoints(tnode *n, int y, int x) {
    if (!n || !isValidRange(n, y, x)) return 0;
    if (n->sx == n->lx && n->sy == n->ly) return n->cnt;
    int ret = 0;
    if (n->L && isValidRange(n->L, y, x)) ret += countPoints(n->L, y, x);
    if (n->R && isValidRange(n->R, y, x)) ret += countPoints(n->R, y, x);
    return ret;
}

bool sortCriteria(int a, int b) {
    return REQ[a][0] < REQ[b][0];
}

