int pric;

struct thing {
    int place, num, t;
} a[maxn];

bool cmp(thing x, thing y) {
    return x.place < y.place || (x.place == y.place && x.t < y.t);
}

int calc(int l, int r, int n) {
    int k = r - l;
    return ((long long)(pric + pric - k + 1) * k / 2) * n % mod;
}

void work() {
    int m;
    scanf("%d%d", &pric, &m);
    int old = calc(1, maxn, m);
    for (int i = 1; i <= m; i++) {
        scanf("%d%d", &a[i].place, &a[i].num);
        a[i].t = 0;
        a[i + m].place = a[i].place;
        a[i + m].num = a[i].num;
        a[i + m].t = 1;
    }
    sort(a + 1, a + 2 * m + 1, cmp);
    map<int, int> ticket;
    int ans = 0;
    for (int i = 1; i <= 2 * m; i++) {
        if (a[i].t == 0) {
            ticket[a[i].place] += a[i].num;
        } else {
            map<int, int>::reverse_iterator it;
            for (it = ticket.rbegin(); it != ticket.rend(); it++) {
                if (it->first <= a[i].place) break;
                ans = (ans + calc(a[i].place, it->first, min(it->second, a[i].num))) % mod;
                if (it->second > a[i].num) {
                    it->second -= a[i].num;
                    a[i].num = 0;
                    break;
                } else {
                    a[i].num -= it->second;
                    ticket.erase(prev(it.base()));
                }
            }
        }
    }
    printf("%d\n", (old - ans + mod) % mod);
}

