    dsu(int sz) {
        this->sz = sz;
        f.resize(sz);
        iota(f.begin(), f.end(), 0);
    }

    int get(int i) {
        return f[i] = (f[i] == i ? i : get(f[i]));
    }

    bool un(int i, int j) {
        i = get(i);
        j = get(j);
        if (i == j) return false;
        f[i] = j;
        return true;
    }
};

int sqr(int x) {
    return x * x;
}

void solve(int test) {
    int n;
    cin >> n;
    vector<array<int, 3>> a(n);
    vector<int> s(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 3; ++j) {
            cin >> a[i][j];
        }
        cin >> s[i];
    }

    vector<array<int, 3>> edges;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int d = 0;
            for (int k = 0; k < 3; ++k) {
                d += sqr(a[i][k] - a[j][k]);
            }
            d = sqrt(d) - s[i] - s[j];
            edges.push_back({d, i, j});
        }
    }

    sort(edges.begin(), edges.end());

    dsu d(n);
    int ans = 0;
    for (auto [w, i, j] : edges) {
        if (d.un(i, j)) {
            ans = max(ans, w);
        }
    }

    cout << ans << endl;

    string filename = "thread" + to_string(test) + ".out";
    ofstream fout(filename);
    fout << ans << endl;
    fout.close();

    __inctests();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ifstream fin("input.txt");
    fin >> __tests;
    fin.close();

    if (!__multithreading) {
        for (int test = 1; test <= __tests; ++test) {
            solve(test);
        }
    } else {
        for (int test = 1; test <= __tests; ++test) {
            pid_t pid = fork();
            if (pid == -1) {
                cerr << "Failed to spawn thread" << endl;
                return 1;
            } else if (pid == 0) {
                __id = test;
                solve(test);
                return 0;
            } else {
                __ids.push_back(pid);
            }
            if (__ids.size() >= __limitofthreads) {
                for (auto id : __ids) {
                    int status;
                    waitpid(id, &status, 0);
                }
                __ids.clear();
            }
        }
        for (auto id : __ids) {
            int status;
            waitpid(id, &status, 0);
        }
    }

    ofstream fout("output.txt");
    for (int test = 1; test <= __tests; ++test) {
        string filename = "thread" + to_string(test) + ".out";
        ifstream fin(filename);
        string ans;
        getline(fin, ans);
        fout << ans << endl;
        fin.close();
    }
    fout.close();

    return 0;
}

