#define FOREQ(i,k,n) for(int i=(k);i<=(n);++i)
#define FORIT(i,c) for(__typeof((c).begin()) i=(c).begin();i!=(c).end();++i)
#define SZ(v) ((int)(v).size())
#define MEMSET(v,h) memset((v),h,sizeof(v))

typedef vector<int> V;

int N;
V card;
int arr[1<<16];

void printvi(V &vi) {
    cout << "#";
    FORIT(i,vi) cout << " " << *i;
    cout << endl;
}

int cost(V &vi) {
    if (SZ(vi) == 1) return 0;
    int mask = 0;
    REP(i,SZ(vi)) mask |= (1<<vi[i]);
    int &ret = arr[mask];
    if (ret != -1) return ret;
    ret = INT_MAX;
    REP(i,SZ(vi)) FOR(j,i+1,SZ(vi)) {
        V v1, v2;
        REP(k,SZ(vi)) {
            if (k == i || k == j) v1.push_back(vi[k]);
            else v2.push_back(vi[k]);
        }
        ret = min(ret, max(cost(v1),cost(v2)));
    }
    return ret;
}

void solve() {
    cin >> N;
    card.resize(N);
    REP(i,N) cin >> card[i];
    MEMSET(arr,-1);
    int best = INT_MAX;
    do {
        //printvi(card);
