        //cout << tmp << endl;
        best = min(best, tmp);
    } while(next_permutation(card.begin(),card.end()));
    //cout << best << endl;
    int res = 0;
    REP(i,N) res ^= card[i];
    if (best < (res>>1)) cout << "Constantine emerges victorious!" << endl;
    else cout << "Mike triumphs in the end!" << endl;
}

