using namespace std;

const int N = 5010;

int n, s, t;
int e[N], h[N];
vector<vector<int>> g;
vector<int> cur;

struct Edge {
    int v, cap, flow, back_ind;
    Edge *back;
};

void bfs(int start, int start_h) {
    queue<int> q;
    q.push(start);
    h[start] = start_h;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int i : g[u]) {
            Edge &e = cur[i];
            if (e.cap - e.flow > 0 && h[e.v] == 0) {
                h[e.v] = h[u] + 1;
                q.push(e.v);
            }
        }
    }
}

int compute_flow() {
    int flow = 0;

    for (int u = 0; u < n; u++) {
        e[u] = 0;
        h[u] = 0;
        cur[u] = 0;
    }

    h[s] = n;

    for (int i = 0; i < g[s].size(); i++) {
        Edge &e = cur[g[s][i]];
        int amt = e.cap;
        e.flow += amt;
        e.back->flow -= amt;
        e[e.v] = amt;
    }

    vector<int> hs(2 * n + 1, 0);

    for (int i = 0; i < n; i++) {
        if (i != s && i != t) {
            hs[h[i]]++;
        }
    }

    int hi = n;
    int step = 0;

    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (i != s && i != t && e[i] > 0) {
            q.push(i);
        }
    }

    while (hi >= 0) {
        if (++step == n) {
            bfs(t, 0);
            for (int u = 0; u < n; u++) {
                if (h[u] != 0) {
                    h[u] += n;
                }
            }
            hi = 2 * n;
            step = 0;
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            while (e[u] > 0) {
                if (cur[u] == g[u].size()) {
                    h[u] = numeric_limits<int>::max();
                    for (int i : g[u]) {
                        Edge &e = cur[i];
                        if (e.cap - e.flow > 0) {
                            h[u] = min(h[u], h[e.v] + 1);
                        }
                    }
                    hs[h[u]]++;
                    hi = h[u];
                    break;
                }

                Edge &e = cur[g[u][cur[u]]];
                if (h[e.v] == h[u] - 1 && e.cap - e.flow > 0) {
                    int amt = min(e[u], e.cap - e.flow);
                    e[u] -= amt;
                    e[e.v] += amt;
                    e.flow += amt;
                    e.back->flow -= amt;
                    if (e[e.v] > 0 && e.v != t) {
                        q.push(e.v);
                    }
                } else {
                    cur[u]++;
                }
            }

            if (h[u] < n) {
                hs[h[u]]--;
                while (hi >= 0 && hs[hi] == 0) {
                    hi--;
                }
            }
        }

        flow += e[t];
        e[t] = 0;
    }

    return flow;
}

void add_edge(int a, int b, int c, int c_back = 0) {
    assert(a != b);

    Edge e1 = {b, c, 0, static_cast<int>(g[b].size()), nullptr};
    Edge e2 = {a, c_back, 0, static_cast<int>(g[a].size()), nullptr};

    g[a].push_back(static_cast<int>(cur.size()));
    cur.push_back(e1);
    g[b].push_back(static_cast<int>(cur.size()));
    cur.push_back(e2);

    cur[cur.size() - 2].back = &cur[cur.size() - 1];
    cur[cur.size() - 1].back = &cur[cur.size() - 2];
}

int main() {
    int T;
    cin >> T;

    while (T--) {
        int R, C;
        cin >> R >> C;

        n = R * C + 2;
        s = n - 2;
        t = n - 1;

        g.assign(n, vector<int>());
        cur.clear();
        cur.reserve(2 * (R * (C - 1) + C * (R - 1) + 2 * R * C));

        vector<vector<char>> grid(R, vector<char>(C));
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                cin >> grid[i][j];
            }
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                int u = i * C + j;
                if (grid[i][j] == '#') continue;
                if (i == 0) {
                    add_edge(s, u, 1);
                }
                if (i == R - 1) {
                    add_edge(u, t, 1);
                }
                if (i + 1 < R && grid[i + 1][j] != '#') {
                    add_edge(u, (i + 1) * C + j, 1);
                }
                if (j + 1 < C && grid[i][j + 1] != '#') {
                    add_edge(u, i * C + (j + 1), 1);
                }
            }
        }

        cout << compute_flow() << endl;
    }

    return 0;
}

