#include <iostream>
#include <cmath>
#include <cstring>
using namespace std;
typedef long long ll;

const ll MOD = 1000000007;
const int Maxn = 100007;
ll factorial[Maxn], inverseFactorial[Maxn];
int primesArray[Maxn], primesCount;
int sieve[Maxn];
int n, m;

ll powerModulo(ll base, ll exponent) {
    ll result = 1;
    while (exponent) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

void precomputeFactorials() {
    factorial[0] = 1;
    for (int i = 1; i < Maxn; i++) {
        factorial[i] = factorial[i - 1] * i % MOD;
    }
    inverseFactorial[Maxn - 1] = powerModulo(factorial[Maxn - 1], MOD - 2);
    for (int i = Maxn - 2; i >= 0; i--) {
        inverseFactorial[i] = inverseFactorial[i + 1] * (i + 1) % MOD;
    }
}

ll binomialCoefficient(ll n, int k) {
    return factorial[n] * inverseFactorial[k] % MOD * inverseFactorial[n - k] % MOD;
}

void generatePrimes() {
    memset(sieve, 0, sizeof(sieve));
    for (int i = 2; i < Maxn; i++) {
        if (!sieve[i]) primesArray[primesCount++] = i;
        for (int j = 0; j < primesCount && i * primesArray[j] < Maxn; j++) {
            sieve[i * primesArray[j]] = primesArray[j];
            if (i % primesArray[j] == 0) break;
        }
    }
}

int mobius(int x) {
    int factors = 0;
    while (x > 1) {
        int p = sieve[x];
        if (p == 0) p = x;
        if (x % (p * p) == 0) return 0;
        x /= p;
        factors ^= 1;
    }
    return factors ? -1 : 1;
}

int main() {
    generatePrimes();
    precomputeFactorials();
    for (n = 1; n <= 100000; n++) {
        m = max(n / 2 - 1, 1);
        ll result = 0;
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                result += mobius(i) * binomialCoefficient(m, n / i - 1);
            }
        }
        result %= MOD;
        if (result < 0) result += MOD;
        if (result < 0) cout << n << " " << result << endl;
    }
    return 0;
}

