bool cw(const point &a, const point &b, const point &c) {
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

vector<point> convexHull(vector<point> p) {
    int n = p.size();
    if (n <= 2) return p;
    sort(p.begin(), p.end());
    vector<point> up, down;
    point p1 = p[0], p2 = p.back();
    up.push_back(p1);
    down.push_back(p1);
    for (int i = 1; i < n; i++) {
        if (i == n - 1 || cw(p1, p[i], p2)) {
            while (up.size() >= 2 && !cw(up[up.size() - 2], up[up.size() - 1], p[i]))
                up.pop_back();
            up.push_back(p[i]);
        }
        if (i == n - 1 || !cw(p1, p[i], p2)) {
            while (down.size() >= 2 && cw(down[down.size() - 2], down[down.size() - 1], p[i]))
                down.pop_back();
            down.push_back(p[i]);
        }
    }
    vector<point> hull;
    for (int i = 0; i < up.size(); i++)
        hull.push_back(up[i]);
    for (int i = down.size() - 2; i > 0; i--)
        hull.push_back(down[i]);
    return hull;
}

bool on_line(point x, point a, point b) {
    return (x.x - a.x) * (b.y - a.y) == (x.y - a.y) * (b.x - a.x);
}

