    long long sum = 0;
    for (char c : str) {
        sum += c - '0';
    }
    return sum > str.length();
}

bool isSingleString(const string &str) {
    long long sum = 0;
    for (int i = 0; i < str.length(); i++) {
        sum += (i + 1) * (str[i] - '0');
    }
    return sum > str.length();
}

void generateNextString(vector<int> count, string currentString, int x) {
    if (x == count.size()) {
        uniqueStrings.insert(currentString);
        return;
    }
    for (int i = 0; i < count.size(); i++) {
        if (count[i] == 0) continue;
        count[i]--;
        generateNextString(count, currentString + char(i + '0'), x + 1);
        count[i]++;
    }
}

void exploreStrings(const string &str) {
    if (uniqueStrings.count(str)) return;
    uniqueStrings.insert(str);
    if (isSingleString(str)) {
        vector<int> characterCount(10);
        for (char c : str) {
            characterCount[c - '0']++;
        }
        long long result = factorial[str.length()];
        for (int i = 0; i < 10; i++) {
            result /= factorial[characterCount[i]];
        }
        deadCount += result;
        return;
    }
    vector<int> characterCount(10);
    for (char c : str) {
        characterCount[c - '0']++;
    }
    generateNextString(characterCount, "", 0);
}

void generateFactorials() {
    factorial[0] = 1;
    for (int i = 1; i < 10; i++) {
        factorial[i] = factorial[i - 1] * i;
    }
