#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = a; i < (b); ++i)
#define all(x) begin(x), end(x)
#define sz(x) (int)(x).size()
typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

const int MAXN = 310;
const int MAXVN = MAXN+2;
int dist_inf = 1000000000;
int flow_inf = 1000000000;

struct Arc {
	int to, rev, cap, flow;
};

struct DinicFlow {

	int d[MAXVN], ptr[MAXVN];
	vector<int> adj[MAXVN];
	vector<Arc> arcs;
	int que[MAXVN], qf, qb, nodes;
	int source, sink;

	void init(int x) {
		nodes = x;
		arcs.clear();
		rep(i,0,nodes) {
			adj[i].clear();
		}
	}

	void append(int from, int to, int cap) {
		Arc a1 = {to, sz(arcs[to]), cap, 0};
		Arc a2 = {from, sz(arcs[from]), 0, 0};
		adj[from].push_back(sz(arcs)); arcs.push_back(a1);
		adj[to].push_back(sz(arcs)); arcs.push_back(a2);
	}

	int bfs_layer() {
		rep(i,0,nodes) d[i] = -1;
		qf=qb=0;
		que[qb++] = source;
		d[source] = 0;
		while(qf < qb && d[sink] == -1) {
			int x = que[qf++];
			rep(i,0,sz(adj[x])) {
				int y = arcs[adj[x][i]].to;
				if(d[y] == -1 && arcs[adj[x][i]].flow < arcs[adj[x][i]].cap) {
					d[y] = d[x] + 1;
					que[qb++] = y;
				}
			}
		}
		return d[sink] != -1;
	}

	int dfs_push(int x, int flow) {
		if(!flow) return 0;
		if(x == sink) return flow;
		for(; ptr[x] < sz(adj[x]); ptr[x]++) {
			int y = arcs[adj[x][ptr[x]]].to;
			if(d[y] != d[x]+1) continue;
			int pushed = dfs_push(y, min(flow, arcs[adj[x][ptr[x]]].cap - arcs[adj[x][ptr[x]]].flow));
			if(pushed) {
				arcs[adj[x][ptr[x]]].flow += pushed;
				arcs[arcs[adj[x][ptr[x]]].rev].flow -= pushed;
				return pushed;
			}
		}
		return 0;
	}

	int push_flow() {
		int flow = 0;
		while(flow < flow_inf && bfs_layer()) {
			rep(i,0,nodes) ptr[i] = 0;
			while(int pushed = dfs_push(source, flow_inf)) {
				flow += pushed;
			}
		}
		return flow;
	}

	vector<pii> mincut() {
		vector<pii> mct;
		for(int x=0; x < nodes; x++)
			for(int y : adj[x]) if(d[x] >= 0 && d[arcs[y].to] == -1 && arcs[y].cap > 0)
				mct.push_back(pii(x, arcs[y].to));
		return mct;
	}

	vi srccut() {
		vi sct;
		rep(x,0,nodes) if(d[x] >= 0) sct.push_back(x);
		return sct;
	}

	vi sinkcut() {
		vi sct;
		rep(x,0,nodes) if(d[x] == -1) sct.push_back(x);
		return sct;
	}

	bool mincut_is_isolated_sink() {
		return d[sink] == -1;
	}

	int maxflow(int s, int t) {
		source = s, sink = t;
		return push_flow();
	}

};

struct Edge {
	int to, w;
};

int n, m, k;
vector<Edge> edges[MAXN];

void input() {
	cin >> n >> m >> k;
	rep(i,0,m) {
		int a, b, w;
		cin >> a >> b >> w;
		--a; --b;
		edges[a].push_back({b, w});
		edges[b].push_back({a, w});
	}
}

vi dist;

void bfs() {
	dist.assign(n, dist_inf);
	queue<int> q;
	q.push(0);
	dist[0] = 0;
	while(!q.empty()) {
		int x = q.front(); q.pop();
		for(auto e : edges[x]) {
			if(dist[e.to] > dist[x] + 1) {
				dist[e.to] = dist[x] + 1;
				q.push(e.to);
			}
		}
	}
}

void solve() {
	input();
	bfs();
	DinicFlow flow;
	flow.init(n + 2);
	int source = n;
	int sink = n + 1;
	rep(i,0,n-1) {
		if(dist[i] >= dist_inf) continue;
		int w = 0;
		for(auto e : edges[i]) {
			if(dist[e.to] < dist[i]) {
				w += e.w;
			}
		}
		flow.append(i, sink, w);
	}
	flow.append(source, 0, k);
	int f = flow.maxflow(source, sink);
	cout << min(f, k) << endl;
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
	cin.exceptions(cin.failbit);

	int t;
	cin >> t;
	while(t--) {
		solve();
	}
}

