class DisjointSet
{
public:
    vector<int> prev;
    int nSets;

    DisjointSet(int N) : prev(N), nSets(N)
    {
        REP(i, N)
            prev[i] = i;
    }

    int findRoot(int v)
    {
        if (prev[v] == v) return v;
        return prev[v] = findRoot(prev[v]);
    }

    void unite(int u, int v)
    {
        u = findRoot(u); v = findRoot(v);
        if (u == v) return;
        prev[v] = u;
        --nSets;
    }

    int getNumSets() const
    {
        return nSets;
    }
};

int solve()
{
    int a, b, p; cin >> a >> b >> p;
    int nums = b - a + 1;
    DisjointSet ds(nums);

    for (int pr = p; pr < nums; ++pr) if (isPrime(pr))
    {
        int startMul = (a + pr - 1) / pr;
        startMul = max(2, startMul);
        int firstIndex = pr * startMul - a;

        int endMul = b / pr;
        int lastIndex = endMul * pr - a;

        for (int cur = firstIndex; cur + pr <= lastIndex && cur < nums; cur += pr)
            ds.unite(cur, cur + pr);
    }

    return ds.getNumSets();
}

