}

double clamp(double value) {
    return max(-1.0, min(1.0, value));
}

double calculateArea(int xx, int yy) {
    if (x[0] == x[1] && y[0] == y[1] && x[0] == xx && y[0] == yy)
        return 0;
    if ((xx == x[0] && yy == y[0]) || (xx == x[1] && yy == y[1]))
        return 0;
    double distance = calculateDistance(x[0], y[0], x[1], y[1]);
    double lengthA = calculateDistance(xx, yy, x[0], y[0]);
    double lengthB = calculateDistance(xx, yy, x[1], y[1]);
    double cosineA = clamp((lengthA * lengthA + distance * distance - lengthB * lengthB) / (2 * lengthA * distance));
    double cosineB = clamp((lengthB * lengthB + distance * distance - lengthA * lengthA) / (2 * lengthB * distance));
    double area = PI * lengthA * lengthA * (acos(cosineA) / PI) + PI * lengthB * lengthB * (acos(cosineB) / PI) - distance * lengthA * sqrt(1 - cosineA * cosineA);
    return area;
}

