class FordFulkerson {
private:
    vector<vector<Edge>> G;
    vector<bool> used;

public:
    FordFulkerson(int n) {
        G.resize(n);
        used.resize(n);
    }

    void add_edge(int from, int to, int cap) {
        G[from].emplace_back(to, cap, G[to].size());
        G[to].emplace_back(from, 0, G[from].size() - 1);
    }

