        if (v == t) return f;
        used[v] = true;
        for (auto &e : G[v]) {
            if (!used[e.to] && e.cap > 0) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t) {
        int flow = 0;
        while (true) {
            fill(used.begin(), used.end(), false);
            int f = dfs(s, t, INF);
            if (f == 0) return flow;
            flow += f;
        }
    }
};

void solve() {
    cin >> N >> P;

    R.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> R[i];
    }

    Q.resize(N, vector<int>(P));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < P; j++) {
            cin >> Q[i][j];
        }
    }

    vector<vector<int>> xQ(N, vector<int>(P, 0));
    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j < P; j++) {
            xQ[i][j] = max(0, R[i + 1] - Q[i][j]);
            xQ[i + 1][j] = Q[i][j] - R[i];
        }
    }

    FordFulkerson ff(N * P + 2);
    int s = N * P, t = N * P + 1;

    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j < P; j++) {
            ff.add_edge(i * P + j, (i + 1) * P + j, xQ[i + 1][j]);
            ff.add_edge(i * P + j, (i + 1) * P + j, INF - xQ[i + 1][j]);
        }
    }

    for (int j = 0; j < P; j++) {
        ff.add_edge(s, j, xQ[0][j]);
        ff.add_edge(s, j, INF - xQ[0][j]);
        ff.add_edge((N - 1) * P + j, t, INF);
    }

    int maxFlow = ff.max_flow(s, t);
    cout << maxFlow << endl;
}

