int dfsinv(int u, int proib) {
    int tam = 1;
    CC[u] = 1;
    for (int i = 0; i < nadjinv[u]; i++) {
        int v = adjinv[u][i];
        if (v != proib && !CC[v])
            tam += dfsinv(v, proib);
    }
    return tam;
}

void SCC(int u) {
    indx[u] = lowlink[u] = ++I;
    S[++Stop] = u;
    empilhado[u] = true;
    for (int i = 0; i < nadj[u]; i++) {
        int v = adj[u][i];
        if (!indx[v]) {
            SCC(v);
            lowlink[u] = min(lowlink[u], lowlink[v]);
        } else if (empilhado[v]) {
            lowlink[u] = min(lowlink[u], indx[v]);
        }
    }
    if (lowlink[u] == indx[u]) {
        CE++;
        int w;
        int tam = 0;
        do {
            w = S[Stop--];
            empilhado[w] = false;
            CC[w] = CE;
            tam++;
        } while (w != u);
        resp = max(resp, tam);
    }
}

void tarjan() {
