    Stop = 0;
    CE = 0;
    for (int i = 1; i <= n; i++) {
        CC[i] = 0;
        lowlink[i] = -1;
        indx[i] = 0;
        empilhado[i] = false;
    }
    for (int i = 1; i <= n; i++)
        if (!indx[i])
            SCC(i);
