#include <bits/stdc++.h>

using namespace std;

const int DX[] = {-1, 1, 0, 0};
const int DY[] = {0, 0, -1, 1};
const int N = 1005;

char field[N][N];
int queue[N * N][2];
int distanceT[N][N], distance[N][N];
int visitedT[N][N], visited[N][N];
int timerT, timer;
bool forbidden[N][N];

inline bool isWall(int x, int y) { return field[x][y] == '#'; }
inline bool isOutOfBounds(int x, int y) { return x < 0 || x >= N - 1 || y < 0 || y >= N - 1; }

int bfsT(int startX, int startY, int targetX, int targetY, bool firstCall, int currentX, int currentY) {
    if (isOutOfBounds(startX, startY) || isOutOfBounds(targetX, targetY)) return 1e9;
    ++timerT;
    queue[0][0] = targetX, queue[0][1] = targetY;
    int x, y;
    int front = 0, back = 1;
    distanceT[targetX][targetY] = 0;
    visitedT[targetX][targetY] = timerT;
    while (front < back) {
        x = queue[front][0], y = queue[front][1]; front++;
        for (int k = 0; k < 4; k++) {
            int nextX = x + DX[k], nextY = y + DY[k];
            if (isOutOfBounds(nextX, nextY) || visitedT[nextX][nextY] == timerT || (!forbidden[nextX][nextY] && isWall(nextX, nextY)))
                continue;
            if (!firstCall && (nextX == currentX && nextY == currentY)) continue;
            distanceT[nextX][nextY] = distanceT[x][y] + 1;
            queue[back][0] = nextX, queue[back][1] = nextY; back++;
            visitedT[nextX][nextY] = timerT;
        }
    }
    return distanceT[startX][startY];
}

int bfs(int startX, int startY, int targetX, int targetY, bool firstCall, int currentX, int currentY) {
    if (isOutOfBounds(startX, startY) || isOutOfBounds(targetX, targetY)) return 1e9;
    ++timer;
    queue[0][0] = startX, queue[0][1] = startY;
    int x, y;
    int front = 0, back = 1;
    distance[startX][startY] = 0;
    visited[startX][startY] = timer;
    while (front < back) {
        x = queue[front][0], y = queue[front][1]; front++;
        for (int k = 0; k < 4; k++) {
            int nextX = x + DX[k], nextY = y + DY[k];
            if (isOutOfBounds(nextX, nextY) || visited[nextX][nextY] == timer || (!forbidden[nextX][nextY] && isWall(nextX, nextY)))
                continue;
            if (!firstCall && (nextX == currentX && nextY == currentY)) continue;
            distance[nextX][nextY] = distance[x][y] + 1;
            queue[back][0] = nextX, queue[back][1] = nextY; back++;
            visited[nextX][nextY] = timer;
        }
    }
    return distance[targetX][targetY];
}

void solve() {
    #ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    #endif
    memset(field, 0, sizeof(field));
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    for (int i = 0; i < rows; i++)
        scanf("%s", field[i]);
    int startX, startY, targetX, targetY;
    scanf("%d %d %d %d", &startX, &startY, &targetX, &targetY); startX--, startY--, targetX--, targetY--;
    int minX = min(startX, targetX), maxX = max(startX, targetX);
    int minY = min(startY, targetY), maxY = max(startY, targetY);
    for (int x = minX; x <= maxX; x++)
        for (int y = minY; y <= maxY; y++)
            forbidden[x][y] = true;
    int requiredSteps = abs(startX - targetX) + abs(startY - targetY);
    int count = 0;
    while (bfs(startX, startY, targetX, targetY, count == 0, -1, -1) + 1 > cols) {
        if (count == cols * 2) {
            printf("IMPOSSIBLE\n");
            return;
        }
        int currentX = -1, currentY = -1;
        int currentAnswer = 1e9;
        bfs(startX, startY, targetX, targetY, true, 0, 0);
        for (int x = 0; x < rows; x++)
            for (int y = 0; y < rows; y++)
                if (isWall(x, y) && !forbidden[x][y] && !isOutOfBounds(x, y) && !isOutOfBounds(x + 1, y + 1) &&
                    bfsT(startX, startY, x, y, true, 0, 0) + bfsT(x + 1, y + 1, targetX, targetY, true, 0, 0) == requiredSteps) {
                    int currentResult = max(distance[x][y], bfsT(x + 1, y + 1, targetX, targetY, false, x, y));
                    if (currentResult < currentAnswer) {
                        currentAnswer = currentResult;
                        currentX = x, currentY = y;
                    }
                }
        assert(currentX != -1);
        field[currentX][currentY] = field[currentX + 1][currentY] = field[currentX][currentY + 1] = field[currentX + 1][currentY + 1] = '.';
        forbidden[currentX][currentY] = forbidden[currentX + 1][currentY] = forbidden[currentX][currentY + 1] = forbidden[currentX + 1][currentY + 1] = true;
        count++;
    }
    if (bfs(startX, startY, targetX, targetY, false, -1, -1) != requiredSteps) {
        printf("IMPOSSIBLE\n");
        return;
    }
    printf("POSSIBLE\n");
    for (int i = 0; i < rows; i++)
        printf("%s\n", field[i]);
}

