long long det(long long a, long long b, long long c, long long d, long long e, long long f, long long g, long long h, long long i) {
    return a * e * i + b * f * g + c * d * h - c * e * g - b * d * i - a * f * h;
}

int signum(long long x) {
    if (x < 0) return -1;
    if (x > 0) return 1;
    return 0;
