        for (pii p : cur) {
            res[p.first] = p;
            for (pii pp : trans[p])
                nxt.insert(pp);
        }
        cur = nxt;
    }
}

void run() {
    queue<pii> q;
    q.push({ 1, 1 }); q.push({ 1, 0 });
    while (!q.empty()) {
        pii p = q.front(); q.pop();
        if (p.first >= maxn)
            continue;
        res[p.first] = p;
        if (res.size() == 9906)
            break;
        vector<pii> to = trans[p];
        for (pii pp : to) {
            prev[pp] = { p, to.size() };
            q.push(pp);
        }
    }
}

