    b.assign(n, vector<long double>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            b[i][j] = a[i][j];
    return gaub(b) == 1;
}

void finalize() {
    for (int i = 0; i < n; ++i) {
        bool ok = false;
        for (int j = 0; j < n; ++j)
            if (a[i][j])
                ok = true;
        if (!ok)
            a[i][i] = 1;
    }
}

void ae(int x, int y) {
    a[x][y] = a[y][x] = 1;
}

void restore(pii p) {
    if (p.first == 1)
        return;
    pii pp = prev[p].first;
    int size = prev[p].second;
    restore(pp);
    for (int i = 0; i < size; ++i) {
        ae(n, n + 1);
        ++n;
    }
}

