    pow2[0] = 1;
    for (int i = 1; i <= 41; i++)
        pow2[i] = pow2[i - 1] * 2;

    for (int i = 0; i < t; i++) {
        long long P, Q;
        scanf("%lld/%lld", &P, &Q);

        long long d = gcd(P, Q);
        P /= d;
        Q /= d;

        bool feasible = false;
        for (int j = 1; j <= 41; j++) {
            if (Q == pow2[j]) {
                feasible = true;
                break;
            }
        }

        if (!feasible) {
            printf("Case #%d: impossible\n", i + 1);
            continue;
        }

        int generations = 0;
        for (int j = 1; j <= 41; j++) {
            if (pow2[j] >= (Q + P - 1) / P) {
                generations = j;
                break;
            }
        }

        printf("Case #%d: %d\n", i + 1, generations);
    }

    return 0;
}

