        double probability_sum = 0.0;
        double probability_product = 1.0;
        for (int i = 0; i < num_probs; ++i) {
            std::cin >> probabilities[i];
            probability_sum += probabilities[i];
            probability_product *= probabilities[i];
        }

        std::sort(probabilities.rbegin(), probabilities.rend());

        double current_sum = 0.0;
        double optimal_result = probability_product;
        for (int i = 0; i <= num_probs; ++i) {
            if (i > 0) {
                current_sum += probabilities[i - 1];
