                double result = std::pow(individual_probability, num_probs - i);
                optimal_result = std::max(optimal_result, result);
            } else {
                optimal_result = 1.0;
            }
        }

        std::cout << "Case #" << test_case << ": " << std::fixed << std::setprecision(20) << optimal_result << std::endl;
