const int MAXN = 21;
int rows, cols;
int memo[MAXN][MAXN][MAXN][MAXN];

bool isValidMove(int r, int c, int happyState) {
    return r >= 0 && r < rows && c >= 0 && c < cols && (happyState & (1 << (r * cols + c))) == 0;
}

bool processMove(bool aliceTurn, int r, int c, int happyState) {
    if (aliceTurn) {
        for (int i = r + 1; i < rows; i++) {
            if (isValidMove(i, c, happyState)) {
                if (!processMove(!aliceTurn, i, c, happyState | (1 << (i * cols + c)))) {
                    return true;
                }
            } else {
                break;
            }
        }
        for (int i = r - 1; i >= 0; i--) {
            if (isValidMove(i, c, happyState)) {
                if (!processMove(!aliceTurn, i, c, happyState | (1 << (i * cols + c)))) {
                    return true;
                }
            } else {
                break;
            }
        }
    } else {
        for (int j = c + 1; j < cols; j++) {
            if (isValidMove(r, j, happyState)) {
                if (!processMove(!aliceTurn, r, j, happyState | (1 << (r * cols + j)))) {
                    return true;
                }
            } else {
                break;
            }
        }
        for (int j = c - 1; j >= 0; j--) {
            if (isValidMove(r, j, happyState)) {
                if (!processMove(!aliceTurn, r, j, happyState | (1 << (r * cols + j)))) {
                    return true;
                }
            } else {
                break;
            }
        }
    }
    return false;
}

bool determineWinner(bool aliceTurn, int kr, int kc, int happyState) {
    if (memo[kr][kc][kr][kc] != -1) {
        return memo[kr][kc][kr][kc];
    }
    bool result = processMove(aliceTurn, kr, kc, happyState);
    memo[kr][kc][kr][kc] = result;
    return result;
}

