                TURDistances[i][j].clear(), distance[i][j] = -1, dependencies[i][j].clear();

        vector<pair<int, int>> sources, targets;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < M; j++)
                if (A[i][j] == 'S')
                    sources.emplace_back(i, j);
                else if (A[i][j] == 'T')
                    targets.emplace_back(i, j);

        int size = sources.size() + targets.size();
        for (int i = 0; i < sources.size(); i++)
            connected[size][i] = true;
        for (int i = 0; i < targets.size(); i++)
            connected[sources.size() + i][size + 1] = true;

        for (int i = 0; i < sources.size(); i++)
            distance[sources[i].first][sources[i].second] = 0;
        queue<pair<int, int>> Q;
        for (auto p : sources)
            Q.emplace(p);
        while (!Q.empty()) {
            auto u = Q.front();
            Q.pop();
            if (A[u.first][u.second] == 'T')
                TURDistances[u.first][u.second].insert(distance[u.first][u.second]);
            for (int i = 0; i < 4; i++) {
                int r = u.first + dr[i], c = u.second + dc[i];
                if (r < 0 || r >= N || c < 0 || c >= M)
                    continue;
                if (distance[r][c] != -1)
                    continue;
                distance[r][c] = distance[u.first][u.second] + 1;
                Q.emplace(r, c);
            }
        }

        for (int i = 0; i < targets.size(); i++) {
            auto u = targets[i];
            for (int d : TURDistances[u.first][u.second]) {
                int r = u.first, c = u.second;
                if (d == 0)
                    dependencies[r][c].insert(d);
                for (int j = 0; j < d; j++) {
                    r += dr[2];
                    c += dc[2];
                    dependencies[r][c].insert(d);
                }
            }
        }

        for (int i = 0; i < sources.size(); i++) {
            auto s = sources[i];
            for (int d : TURDistances[s.first][s.second]) {
                int r = s.first + d * dr[2], c = s.second + d * dc[2];
                connected[i][sources.size() + targets.size()] = true;
                connectionDeps[i][sources.size() + targets.size()] = dependencies[r][c];
            }
        }

        int flow = 0;
        while (depthFirstSearch(size, size + 1))
            flow++;

        vector<pair<int, int>> assignment(targets.size());
        vector<int> reverseAssignment(sources.size());
        for (int i = 0; i < sources.size(); i++)
            reverseAssignment[i] = connected[i][size] ? sources.size() : -1;
        for (int i = 0; i < targets.size(); i++)
            assignment[i] = make_pair(-1, -1);

        for (int it = 0; it < targets.size(); it++) {
            fill(visited, visited + size, false);
            for (int i = 0; i < sources.size(); i++)
                if (reverseAssignment[i] >= sources.size())
                    depthFirstSearch2(i, reverseAssignment[i], reverseAssignment, assignment);
            bool flag = false;
            for (int i = 0; i < sources.size(); i++)
                if (reverseAssignment[i] >= sources.size())
                    flag = true;
            if (!flag)
                break;
        }

        cout << flow << '\n';
        for (auto p : assignment)
            if (p.first != -1)
                cout << p.second + 1 << ' ' << p.first + 1 << '\n';
    }

    return 0;
}

