void solve() {
    int r, c;
    cin >> r >> c;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> f[i][j];
        }
    }
    int ans = 0;
    for (int mask = 0; mask < (1 << (r * c)); mask++) {
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                m[i][j] = (mask >> (i * c + j)) & 1;
            }
        }
        bool isValid = true;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                int neighborCount = 0;
                for (int k = 0; k < 9; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];
                    if (ni >= 0 && ni < r && nj >= 0 && nj < c) {
                        neighborCount += m[ni][nj];
                    }
                }
                if (neighborCount != f[i][j]) {
                    isValid = false;
                    break;
                }
            }
            if (!isValid) break;
        }
        if (isValid) {
            int count = 0;
            for (int j = 0; j < c; j++) {
                count += m[r / 2][j];
            }
            ans = max(ans, count);
        }
    }
    cout << "Case #" << test << ": " << ans << endl;
}

