using namespace std;

typedef set<string> trie;
typedef vector<trie> config_t;

int numstr, numserv;
vector<trie> have;
map<config_t, int> ways;

trie maketrie(const string &s) {
    trie ret;
    for (int i = 0; i <= s.length(); i++) {
        ret.insert(s.substr(0, i));
    }
    return ret;
}

void go(int at, config_t &cur, int anymask) {
    if (at == numstr) {
        ways[cur]++;
        return;
    }
    for (int i = 0; i < numserv; i++) {
        if (anymask & (1 << i)) {
            trie tmp = cur[i];
            cur[i].insert(have[at].begin(), have[at].end());
            go(at + 1, cur, anymask & ~(1 << i));
            cur[i] = tmp;
        } else {
            cur[i] = have[at];
            go(at + 1, cur, anymask | (1 << i));
            cur[i].clear();
        }
    }
}

void solve(int testcase) {
    cin >> numstr >> numserv;
    have.clear();
    string s;
    for (int i = 0; i < numstr; i++) {
        cin >> s;
        have.push_back(maketrie(s));
    }
    ways.clear();
    config_t cur(numserv);
    go(0, cur, 0);
    int maxsize = 0, answer = 0;
    for (map<config_t, int>::iterator it = ways.begin(); it != ways.end(); it++) {
        int size = 0;
        for (int i = 0; i < numserv; i++) {
            size += it->first[i].size();
        }
        if (size > maxsize) {
            maxsize = size;
            answer = it->second;
        } else if (size == maxsize) {
            answer += it->second;
        }
    }
    cout << "Case #" << testcase << ": " << maxsize << " " << answer << endl;
}

int main() {
    int T;
    cin >> T;
    for (int testcase = 1; testcase <= T; testcase++) {
        solve(testcase);
    }
    return 0;
}

