        if (averageDistance > 1e-6) {
            cout << "No Solution\n";
        } else {
            double answerX = t1[0].F*v0+t1[1].F*v1+t1[2].F*v2;
            double answerY = t1[0].S*v0+t1[1].S*v1+t1[2].S*v2;
            cout << answerX << " " << answerY << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;

int n;
int l[16], r[16];
int u[1 << 10][16];

void read() {
    scanf("%d", &n);
    for (int i = 1; i <= n - 1; i++) {
        scanf("%d%d", &l[i], &r[i]);
    }
}

void solve() {
    memset(u, 0, sizeof(u));
    int cur = 1, mask = 0, ans = 0;
    u[mask][cur] = 1;
    while (true) {
        int next = ((mask >> (cur - 1)) & 1) ? r[cur] : l[cur];
        if (u[mask][next]) {
            printf("The journey is infinite!\n");
            return;
        }
        u[mask][next] = 1;
        ans++;
        if (next == n) break;
        cur = next;
        mask ^= (1 << (cur - 1));
    }
    printf("The journey spans %d steps.\n", ans);
}

int main() {
    int t;
    scanf("%d", &t);
    for (int i = 1; i <= t; i++) {
        read();
        printf("Scenario %d: ", i);
        solve();
    }
    return 0;
}

