bool isHappy(int k, int b) {
    int history[500], count = 0;
    while (1) {
        convert(k, b);
        int sum = 0;
        for (int j = number[0]; j > 0; j--) {
            sum += number[j] * number[j];
        }
        if (sum == 1)
            return true;
        int i;
        for (i = 1; i <= count; i++)
            if (sum == history[i])
                break;
        if (i <= count)
            return false;
        history[++count] = sum;
        k = sum;
    }
}

void convert(int n, int b) {
    int i = 0;
    while (n > 0) {
        number[++i] = n % b;
        n /= b;
    }
    number[0] = i;
}

