#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAX = 500;
vector<string> M;
vector<string> queries;
string curr[MAX][MAX][MAX], next[MAX][MAX][MAX];

bool mygreater(const string& a, const string& b) {
    if (a.size() != b.size())
        return a.size() > b.size();
    return a > b;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        int W, Q;
        cin >> W >> Q;
        M.resize(W);
        for (int i = 0; i < W; i++)
            cin >> M[i];
        queries.resize(Q);
        vector<int> q(Q);
        for (int i = 0; i < Q; i++)
            cin >> q[i];
        memset(curr, 0, sizeof(curr));
        for (int i = 0; i < W; i++) {
            for (int j = 0; j < W; j++) {
                curr[i][j][M[i][j] - '0'] = M[i][j];
            }
        }
        while (true) {
            for (int i = 0; i < Q; i++) {
                for (int r = 0; r < W; r++) {
                    for (int c = 0; c < W; c++) {
                        if (!curr[r][c][q[i]].empty()) {
                            if (mygreater(curr[r][c][q[i]], queries[i]))
                                queries[i] = curr[r][c][q[i]];
                        }
                    }
                }
            }
            bool done = true;
            for (int i = 0; i < Q; i++) {
                if (queries[i].empty()) {
                    done = false;
                    break;
                }
            }
            if (done)
                break;
            memset(next, 0, sizeof(next));
            for (int i = 0; i < W; i++) {
                for (int j = 0; j < W; j++) {
                    for (int s = 0; s < MAX; s++) {
                        if (!curr[i][j][s].empty()) {
                            string str = curr[i][j][s];
                            if (i > 0) {
                                int ns = s + (M[i - 1][j] == '+' ? 1 : -1) * (M[i - 1][j] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i - 1][j], next[i - 1][j][ns]))
                                    next[i - 1][j][ns] = str + M[i - 1][j];
                            }
                            if (i < W - 1) {
                                int ns = s + (M[i + 1][j] == '+' ? 1 : -1) * (M[i + 1][j] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i + 1][j], next[i + 1][j][ns]))
                                    next[i + 1][j][ns] = str + M[i + 1][j];
                            }
                            if (j > 0) {
                                int ns = s + (M[i][j - 1] == '+' ? 1 : -1) * (M[i][j - 1] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i][j - 1], next[i][j - 1][ns]))
                                    next[i][j - 1][ns] = str + M[i][j - 1];
                            }
                            if (j < W - 1) {
                                int ns = s + (M[i][j + 1] == '+' ? 1 : -1) * (M[i][j + 1] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i][j + 1], next[i][j + 1][ns]))
                                    next[i][j + 1][ns] = str + M[i][j + 1];
                            }
                        }
                    }
                }
            }
            swap(curr, next);
        }
        for (int i = 0; i < Q; i++)
            cout << queries[i] << endl;
        cout << endl;
    }
    return 0;
}

