    for (int l = 0; l < t; l++) {
        int n, a, b, c, d, x0, y0, m;
        cin >> n >> a >> b >> c >> d >> x0 >> y0 >> m;

        int x[n], y[n];
        x[0] = x0;
        y[0] = y0;

        for (int i = 1; i < n; i++) {
            x[i] = (a * x[i-1] + b) % m;
            y[i] = (c * y[i-1] + d) % m;
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                for (int k = j+1; k < n; k++) {
                    if (x[i] == x[j] && y[i] == y[j]) continue;
                    if (x[i] == x[k] && y[i] == y[k]) continue;
                    if (x[j] == x[k] && y[j] == y[k]) continue;
                    if ((x[i] + x[j] + x[k]) % 3 == 0 && (y[i] + y[j] + y[k]) % 3 == 0) count++;
                }
            }
        }

        cout << "Case #" << l+1 << ": " << count << endl;
    }

    return 0;
}

